    out = [row[:] for row in grid]

    for r in range(rows):
        for cc in range(cols):
            if grid[r][cc] != background:
                val = grid[r][cc]
                for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    for k in range(1, 17):
                        nr, nc = r + dr * k, cc + dc * k
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if out[nr][nc] == background:
                                out[nr][nc] = val
                        else:
                            break
    return out

