def transform(grid):
    from collections import Counter
    bg_counts = Counter(val for row in grid for val in row)
    background = bg_counts.most_common(1)[0][0]

    rows = len(grid)
    cols = len(grid[0])
    out = [row[:] for row in grid]

    # Find same-colored pairs at distance-√2
    same_color_pairs = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                val = grid[r][c]
                if val not in same_color_pairs:
                    same_color_pairs[val] = []
                for r2 in range(rows):
                    for c2 in range(cols):
                        if grid[r2][c2] == val and abs(r-r2)==1 and abs(c-c2)==1:
                            pair = tuple(sorted([(r,c),(r2,c2)]))
                            if pair not in same_color_pairs[val]:
                                same_color_pairs[val].append(pair)

    # For each pair, extend both cells away from the pair
    for val, pairs in same_color_pairs.items():
        for (r1,c1), (r2,c2) in pairs:
            dr = r2 - r1  # direction from cell 1 to cell 2
            dc = c2 - c1

            # Extend from cell 1 going in direction (-dr, -dc)
            for k in range(1, 25):
                nr, nc = r1 - dr * k, c1 - dc * k
                if 0 <= nr < rows and 0 <= nc < cols and out[nr][nc] == background:
                    out[nr][nc] = val
                elif k >= 1 and not (0 <= nr < rows and 0 <= nc < cols):
                    break

            # Extend from cell 2 going in direction (dr, dc)
            for k in range(1, 25):
                nr, nc = r2 + dr * k, c2 + dc * k
                if 0 <= nr < rows and 0 <= nc < cols and out[nr][nc] == background:
                    out[nr][nc] = val
                elif k >= 1 and not (0 <= nr < rows and 0 <= nc < cols):
                    break

    return out

